/** Requires a deliberate target and rejects URI/database mismatches without exposing credentials. */
function validateTarget(database, uri) {
  if (!database || !/^[a-zA-Z][a-zA-Z0-9_-]{0,62}$/.test(database) ||
      ['admin', 'local', 'config', 'test'].includes(database.toLowerCase())) {
    throw new SeedError('Supply --database with an explicit application database name; system/default databases are refused.');
  }
  if (!uri) throw new SeedError('Set MONGO_URI privately in the backend .env file before using --apply.');
  let parsed;
  try {
    parsed = new URL(uri);
  } catch {
    throw new SeedError('MONGO_URI is not a valid MongoDB URI. Check the Atlas Drivers connection string.');
  }
  if (!['mongodb:', 'mongodb+srv:'].includes(parsed.protocol)) {
    throw new SeedError('MONGO_URI must use mongodb:// or mongodb+srv://.');
  }
  if (parsed.pathname !== `/${database}`) {
    throw new SeedError('The database path in MONGO_URI must exactly match --database. No implicit target is allowed.');
  }
}

/** Refuses any database containing documents, including non-application collections. */
async function assertEmptyDatabase(db, session) {
  const collections = await db.listCollections({}, { nameOnly: true }).toArray();
  for (const { name } of collections) {
    if (name.startsWith('system.')) continue;
    const existing = await db.collection(name).findOne({}, { session, projection: { _id: 1 } });
    if (existing) {
      throw new SeedError('Target database already contains documents. Nothing was overwritten; choose a new empty demo database.');
    }
  }
}

/** Inserts all demo records atomically and verifies them; never deletes or replaces existing records. */
async function applyDemo(database, uri, demo) {
  validateTarget(database, uri);
  try {
    await mongoose.connect(uri, { dbName: database, autoCreate: false, autoIndex: false });
    const db = mongoose.connection.db;
    await assertEmptyDatabase(db);
    for (const Model of [Village, User, Complaint]) {
      await Model.createCollection();
      await Model.createIndexes();
    }
    const session = await mongoose.startSession();
    try {
      await session.withTransaction(async () => {
        await assertEmptyDatabase(db, session);
        await Village.insertMany(demo.villages.map((doc) => doc.toObject()), { session });
        await User.insertMany(demo.users.map((doc) => doc.toObject()), { session });
        await Complaint.insertMany(demo.complaints.map((doc) => doc.toObject()), { session });
        for (const [Model, records] of [[Village, demo.villages], [User, demo.users], [Complaint, demo.complaints]]) {
          const count = await Model.countDocuments({ _id: { $in: records.map((doc) => doc._id) } }).session(session);
          if (count !== records.length) throw new SeedError('Inserted record verification failed; transaction will be rolled back.');
        }
      });
    } finally {
      await session.endSession();
    }
    for (const [Model, records] of [[Village, demo.villages], [User, demo.users], [Complaint, demo.complaints]]) {
      const count = await Model.countDocuments({ _id: { $in: records.map((doc) => doc._id) } });
      if (count !== records.length) {
        throw new SeedError('Post-commit verification failed. Data may have been committed; inspect the target before retrying.');
      }
    }
    console.log(`Demo seed committed and verified in database "${database}".`);
  } finally {
    await mongoose.disconnect();
  }
}

